package spoof

import (
	"encoding/hex"
	"strings"
	"testing"
)

// Vectors generated by the reference Python implementation
// (utils/packet_templates.py, ClientHelloMaker.get_client_hello_with) with
// rnd=bytes(range(32)), sess_id=bytes(range(32,64)), key_share=bytes(range(64,96)).
// These pin the Go port to byte-for-byte parity with upstream.
var goldenVectors = map[string]string{
	"auth.vercel.com": "",
	"mci.ir":          "",
	"a":               "",
}

func testFields() (rnd, sessID, keyShare [32]byte) {
	for i := 0; i < 32; i++ {
		rnd[i] = byte(i)
		sessID[i] = byte(i + 32)
		keyShare[i] = byte(i + 64)
	}
	return
}

func TestBuildClientHelloMatchesUpstream(t *testing.T) {
	rnd, sessID, keyShare := testFields()
	for sni, want := range goldenVectors {
		got, err := BuildClientHello(rnd, sessID, keyShare, sni)
		if err != nil {
			t.Fatalf("sni %q: %v", sni, err)
		}
		if h := hex.EncodeToString(got); h != want {
			t.Errorf("sni %q mismatch\n got: %s\nwant: %s", sni, h, want)
		}
	}
}

// A 100-byte SNI exercises the padding shrink at the far end of the range.
func TestBuildClientHelloLongSNI(t *testing.T) {
	rnd, sessID, keyShare := testFields()
	const want = ""
	got, err := BuildClientHello(rnd, sessID, keyShare, strings.Repeat("x", 100))
	if err != nil {
		t.Fatal(err)
	}
	if h := hex.EncodeToString(got); h != want {
		t.Errorf("mismatch\n got: %s\nwant: %s", h, want)
	}
}

// The record size must not move with the SNI, since DPI fingerprints on it.
func TestClientHelloSizeIsConstant(t *testing.T) {
	rnd, sessID, keyShare := testFields()
	for n := 1; n <= MaxFakeSNILen; n++ {
		got, err := BuildClientHello(rnd, sessID, keyShare, strings.Repeat("s", n))
		if err != nil {
			t.Fatalf("sni len %d: %v", n, err)
		}
		if len(got) != ClientHelloSize {
			t.Fatalf("sni len %d: built %d bytes, want %d", n, len(got), ClientHelloSize)
		}
	}
}

func TestBuildClientHelloRejectsBadSNI(t *testing.T) {
	rnd, sessID, keyShare := testFields()
	for _, tc := range []struct{ name, sni string }{
		{"empty", ""},
		{"too long", strings.Repeat("x", MaxFakeSNILen+1)},
	} {
		if _, err := BuildClientHello(rnd, sessID, keyShare, tc.sni); err == nil {
			t.Errorf("%s: expected an error, got nil", tc.name)
		}
	}
}

func TestRandomClientHelloVaries(t *testing.T) {
	a, err := RandomClientHello("auth.vercel.com")
	if err != nil {
		t.Fatal(err)
	}
	b, err := RandomClientHello("auth.vercel.com")
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(a) == hex.EncodeToString(b) {
		t.Error("two random ClientHellos are identical; randomisation is broken")
	}
	if len(a) != ClientHelloSize || len(b) != ClientHelloSize {
		t.Errorf("sizes %d/%d, want %d", len(a), len(b), ClientHelloSize)
	}
}
